import { cn } from "@/lib/utils";
import type { MakerBrandId } from "@/components/icons/maker-brand";

export interface BrandGlyphProps {
  brand: MakerBrandId;
  /** Brand color when true; `currentColor` when false. */
  colored?: boolean;
  className?: string;
}

function glyphFill(colored: boolean, brandColor: string): string {
  const isBlack = brandColor === "#000000" || brandColor === "#191919";
  if (!colored) return "currentColor";
  return isBlack ? "currentColor" : brandColor;
}

function GlyphSvg({
  className,
  children,
}: {
  className?: string;
  children: React.ReactNode;
}) {
  return (
    <svg viewBox="0 0 24 24" aria-hidden className={cn("shrink-0", className)}>
      {children}
    </svg>
  );
}

